// Training — slow, iterative, happens offline/periodically
for (let epoch = 0; epoch < numEpochs; epoch++) {
  const predictions = model.forward(trainingData);
  const loss = computeLoss(predictions, trueLabels);
  model.backward(loss); // update weights
}

// Inference — fast, single forward pass, happens per request in production
const prediction = model.predict(newInput);

// Conceptual: L2 regularization adds a penalty for large weights to the loss function
const loss = predictionError + lambda * sumOfSquaredWeights;
// Larger lambda -> stronger penalty against complex/large weights -> less overfitting,
// but too large risks underfitting by over-constraining the model.

// A single neuron's computation, conceptually
function neuron(inputs, weights, bias, activation) {
  const weightedSum = inputs.reduce((sum, x, i) => sum + x * weights[i], bias);
  return activation(weightedSum);
}

const relu = (x) => Math.max(0, x);
const sigmoid = (x) => 1 / (1 + Math.exp(-x));

// Simplified gradient descent update rule, conceptually:
for (let step = 0; step < numSteps; step++) {
  const predictions = model.forward(inputs);
  const loss = computeLoss(predictions, trueLabels);
  const gradients = backpropagate(loss, model); // chain rule, layer by layer

  for (const weight of model.weights) {
    weight.value -= learningRate * gradients[weight.id];
  }
}

// Conceptual CNN architecture (pseudocode, e.g. via a framework like TensorFlow/PyTorch)
const model = sequential([
  conv2d({ filters: 32, kernelSize: 3, activation: 'relu' }),
  maxPooling2d({ poolSize: 2 }),
  conv2d({ filters: 64, kernelSize: 3, activation: 'relu' }),
  maxPooling2d({ poolSize: 2 }),
  flatten(),
  dense({ units: 10, activation: 'softmax' }), // 10-class classification output
]);

// Conceptual self-attention: each token computes a weighted sum of all tokens,
// weighted by learned relevance ('attention scores').
function selfAttention(tokens) {
  return tokens.map((query) => {
    const scores = tokens.map((key) => dotProduct(query, key));
    const weights = softmax(scores);
    return weightedSum(tokens, weights); // blend of all tokens, weighted by relevance
  });
}

