// Conceptual RAG pipeline:
async function ragAnswer(query) {
  const queryEmbedding = await embed(query);
  const relevantDocs = await vectorDb.search(queryEmbedding, { topK: 5 });

  const context = relevantDocs.map(d => d.text).join('\n\n');
  const prompt = `Answer the question using only this context:\n${context}\n\nQuestion: ${query}`;

  return await llm.generate(prompt);
}

// Server-side (Node.js) example calling an LLM API
