const data = await response.json();

// Conceptual frontend streaming consumption
const response = await fetch('/api/chat', { method: 'POST', body: JSON.stringify({ prompt }) });
const reader = response.body.getReader();
const decoder = new TextDecoder();
let fullText = '';

while (true) {
  const { done, value } = await reader.read();
  if (done) break;
  fullText += decoder.decode(value);
  setDisplayedText(fullText); // progressively render as chunks arrive
}

// Conceptual tool definition and handling loop
const tools = [{
  name: 'get_weather',
  description: 'Get current weather for a city',
  parameters: { city: 'string' },
}];

const response = await llm.generate({ messages, tools });

if (response.toolCall) {
  const result = await getWeather(response.toolCall.arguments.city);
  // Send the result back to the model to continue reasoning
  const finalResponse = await llm.generate({
    messages: [...messages, response, { role: 'tool', content: result }],
  });
}

